// The C shim between the generic Swift shell and an ElmLean app compiled to C (native mode).
// Generic: the app is reached only through `elm_app_initialize` (generated by framework/native/scripts/
// ios_lean_sources.sh: it calls the app's root module initializer) and the `elmlean_native_*`
// functions exported by ElmLean.Native.
#include <lean/lean.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "elmlean_native.h"

lean_object *elm_app_initialize(void);
lean_object *elmlean_native_start(lean_object *);
lean_object *elmlean_native_event(lean_object *);
lean_object *elmlean_native_drain(lean_object *);
lean_object *elmlean_native_system(lean_object *);
lean_object *elmlean_native_cap_result(lean_object *);
lean_object *elmlean_native_wait(lean_object *);
// in libleanrt but not in lean.h: registers a thread Lean did not create
void lean_initialize_thread(void);
void lean_initialize_runtime_module(void);

// Modules that import anything under `Lean` (ElmLean.Json uses Lean.Data.Json) call `lean_initialize()`
// before their own initializers. The toolchain's version starts the whole compiler (kernel, elaborator,
// dynamic loading), none of which an app uses and none of which is linked; the runtime is enough.
void lean_initialize(void) { lean_initialize_runtime_module(); }

int elmlean_boot(void) {
    lean_object *res = elm_app_initialize();
    lean_io_mark_end_initialization();
    if (!lean_io_result_is_ok(res)) {
        lean_io_result_show_error(res);
        lean_dec_ref(res);
        return 1;
    }
    lean_dec_ref(res);
    lean_init_task_manager();
    return 0;
}

// A thread Lean did not create must be registered before it calls into Lean.
static pthread_key_t registered_key;
static pthread_once_t registered_once = PTHREAD_ONCE_INIT;
static void make_key(void) { pthread_key_create(&registered_key, NULL); }
static void enter_lean(void) {
    pthread_once(&registered_once, make_key);
    if (pthread_getspecific(registered_key) == NULL) {
        lean_initialize_thread();
        pthread_setspecific(registered_key, (void *)1);
    }
}

static char *take_string(lean_object *res) {
    if (!lean_io_result_is_ok(res)) {
        lean_io_result_show_error(res);
        lean_dec_ref(res);
        return strdup("{\"error\":\"lean-io\"}");
    }
    lean_object *s = lean_io_result_get_value(res);
    char *out = strdup(lean_string_cstr(s));
    lean_dec_ref(res);
    return out;
}

static void drop(lean_object *res) {
    if (!lean_io_result_is_ok(res)) lean_io_result_show_error(res);
    lean_dec_ref(res);
}

char *elmlean_start(void) { enter_lean(); return take_string(elmlean_native_start(lean_box(0))); }
char *elmlean_event(const char *json) { enter_lean(); return take_string(elmlean_native_event(lean_mk_string(json))); }
char *elmlean_system(const char *json) { enter_lean(); return take_string(elmlean_native_system(lean_mk_string(json))); }
char *elmlean_drain(void) { enter_lean(); return take_string(elmlean_native_drain(lean_box(0))); }
void elmlean_cap_result(const char *json) { enter_lean(); drop(elmlean_native_cap_result(lean_mk_string(json))); }
void elmlean_wait(void) { enter_lean(); drop(elmlean_native_wait(lean_box(0))); }
